@namespace sv_e5039d8aeb5c4baea767db56fcc58501.Components.Pages.Settings
@using sv_e5039d8aeb5c4baea767db56fcc58501.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="mb-4">
            <h5>Theme</h5>
            @foreach (var theme in _themes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <!-- Font Size Selector -->
        <div class="mb-4">
            <h5>Font Size</h5>
            @foreach (var size in _fontSizes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"size-{size}")" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"size-{size}")">@size</label>
                </div>
            }
        </div>

        <!-- Language Dropdown -->
        <div class="mb-4">
            <h5>Language</h5>
            <select class="form-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode Toggle -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="card mb-4">
            <div class="card-header">Preview</div>
            <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                <h5>Sample Heading</h5>
                <p>This is a preview of how your content will look with the selected settings.</p>
                <button class="btn btn-primary btn-sm">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save")
        </button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">
                Appearance settings saved!
            </div>
