@page "/settings"
@using sv_e5039d8aeb5c4baea767db56fcc58501.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

::deep .settings-sidebar {
    width: 220px;
    border-right: 1px solid var(--bs-border-color, #dee2e6);
    padding: 1.5rem 0;
    background-color: var(--bs-body-bg, #fff);
    flex-shrink: 0;
}

::deep .settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    color: var(--bs-body-color, #212529);
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: background-color 0.15s, border-color 0.15s;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: var(--bs-tertiary-bg, #f8f9fa);
}

::deep .settings-sidebar .nav-link.active {
    background-color: var(--bs-primary-bg-subtle, #e7f1ff);
    border-left-color: var(--bs-primary, #0d6efd);
    font-weight: 600;
}

::deep .sidebar-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
}

